body {
  font-size: 12px;
}

.button {
  width: 100px;
  color: #ff00ff
}

.next-table-fixed table {
  table-layout: fixed;
  background: transparent;
}

td.next-table-cell {
  background-color: transparent !important;
  text-align: center;
}

::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

/* 滚动条轨道 */
::-webkit-scrollbar-track {
  /*  background: rgb(239, 239, 239); */
  border-radius: 5px;
}

/*  小滑块 */
::-webkit-scrollbar-thumb {
  background: #40a0ff49;
  border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
  background: #40a0ff;
}

.table-common {
  width: 100%;
}

.table-common tbody .next-table-cell-wrapper {
  width: 100px;
  /* 限制容器宽度 */
  white-space: nowrap;
  /* 禁止文本换行 */
